sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	//find corresponding email case
	var grEc = new GlideRecord("x_hsb11_hsbcmss_eh_hsbc_email_case");
	grEc.addQuery("qtrack_id",current.object_id);
	//grEc.addQuery("state","IN","1,2");
	grEc.query();
	while (grEc.next()){

	if(current.event_status =="SWB_AUTOMATION_REVIEW_REQUIRED" && grEc.swb_status=="SWB Extract Request Sent Successfully" &&(grEc.state=="1" || grEc.state=="2")){
		grEc.swb_status="SWB Review Required";
		grEc.state='2';
		grEc.update();
	}
	if(current.event_status =="SWB_AUTOMATION_SUCCESS_ALLOCATION.INSTRUCTIONS"){
		grEc.swb_status="SWB Email Successfully Processed";
		if(grEc.swb_payload==""){
		grEc.swb_payload=current.payload;
		}
		grEc.update();
	}
	if(current.event_status =="SWB_AUTOMATION_SUCCESS_CLIENT.AGREE"){
		grEc.swb_status="SWB Email Successfully Processed";
		if(grEc.swb_payload_client_agree==""){
				grEc.swb_payload_client_agree=current.payload;
		}
		grEc.update();
	}
	if(current.event_status =="SWB_AUTOMATION_SUCCESS_CLIENT.DISAGREE"){
		grEc.swb_status="SWB Email Successfully Processed";
		if(grEc.swb_payload_client_disagree==""){
				grEc.swb_payload_client_disagree=current.payload;
		}
		grEc.update();
	}
	if(current.event_status =="SWB_AUTOMATION_UNCATEGORIZED" &&(grEc.state=="1" || grEc.state=="2")){	
		grEc.swb_status="SWB Email Uncategorized";
		grEc.update();
	}	

	if((current.event_status =="SWB_INBOUND_MSG_FAILED" || current.event_status =="SWB_SERVICE_UNAVAILABLE" || current.event_status =="SWB_INDEXING_FAIL")&&(grEc.state=="1" || grEc.state=="2") ){
		grEc.swb_status="SWB Service Unavailable or SWB Inbound Message Failed";
		grEc.update();
	}
	if(current.event_status =="SWB_AUTOMATION_SUCCESS_UNMATCH.AGREE"){// MSSRBXCE-390: If the SWB event response is "Trade Unmatch Agree" then set the payload value to "SWB Payload - Client Agree" field
		grEc.swb_status="SWB Email Successfully Processed";
		if(grEc.swb_payload_client_agree==""){
				grEc.swb_payload_client_agree=current.payload;
		}
		grEc.update();
	}
	if(current.event_status =="SWB_AUTOMATION_SUCCESS_UNMATCH.DISAGREE"){// MSSRBXCE-390: If the SWB event response is "Trade Unmatch Disagree" then set the payload value to "SWB Payload - Client Disagree" field
		grEc.swb_status="SWB Email Successfully Processed";
		if(grEc.swb_payload_client_disagree==""){
				grEc.swb_payload_client_disagree=current.payload;
		}
		grEc.update();
	}
	if(current.event_status =="SWB_AUTOMATION_SUCCESS_UNMATCH.SHAPEDIFF"){// MSSRBXCE-390: If the SWB event response is "Trade Unmatch Shape Difference" then set the payload value to "SWB Payload - Shape Difference" field
		grEc.swb_status="SWB Email Successfully Processed";
		if(grEc.swb_payload_shape_difference==""){
				grEc.swb_payload_shape_difference=current.payload;
		}
		grEc.update();
	}
	if(current.event_status =="SWB_AUTOMATION_SUCCESS_UNMATCH.OTHER"){// MSSRBXCE-390: If the SWB event response is "Trade Unmatch Other Issue" then set the payload value to "SWB Payload - Other Issue" field
		grEc.swb_status="SWB Email Successfully Processed";
		if(grEc.swb_payload_other_issue==""){
				grEc.swb_payload_other_issue=current.payload;
		}
		grEc.update();
	}
	//
	if(current.event_status =="SWB_AUTOMATION_SUCCESS_UNMATCH.TRADENOTRECOGNISED"){// MSSRBXCE-390: MSSRBXCE-522 -If the SWB event response is "Trade Not Recognised" then set the payload value to "SWB Payload - Trade Not Recognised" field
		grEc.swb_status="SWB Email Successfully Processed";
		if(grEc.swb_payload_trade_not_recognised==""){
				grEc.swb_payload_trade_not_recognised=current.payload;
		}
		grEc.update();
	}


	}

})(current, previous);
